files.approve.py:
"""The approval step our harness runs before a browser action commits.

`render` builds the text the human is shown. `approve` records a human yes and
returns a token. `dispatch` is called later, when the action actually runs.
"""


class Action:
    """One proposed action.

    `summary` is a one-line description the MODEL produced.
    `label` is the button text as the FETCHED PAGE reports it.
    `effect` is what the action will really do, decoded from the page by the
        harness itself and not by the model:
        {"op": ..., "target": ..., "amount": ...}
    `kind` is the coarse action class, such as "commit" or "navigate".
    """

    def __init__(self, summary="", label="", effect=None, kind=""):
        self.summary = summary
        self.label = label
        self.effect = effect or {}
        self.kind = kind


def render(action):
    """The text shown to the human."""
    return "Allow this? " + (action.summary or action.label)


def approve(action):
    """Record a human yes and return the token dispatch will check."""
    return {"kind": action.kind}


def dispatch(action, token):
    """Run the action if the token covers it."""
    return bool(token) and token.get("kind") == action.kind

files.permissions.py:
"""Our agent's permission store.

`request_scope` is the authority compiled from the authenticated user request
before the agent ran. `remember` persists a reusable rule so the human is not
asked for the same thing twice.
"""


class Action:
    def __init__(self, command="", op="", target=""):
        self.command = command
        self.op = op
        self.target = target


class Store:
    """Persisted allow-rules for one session.

    `origin` on `remember` is where the rule's scope came from: "request" when
    it was compiled from the authenticated request, or "agent_midtask" when the
    agent proposed it while the task was running.
    """

    def __init__(self, request_scope=()):
        self.request_scope = tuple(request_scope)
        self.rules = []

    def remember(self, prefix, origin="request"):
        self.rules.append(prefix)
        return True

    def allows(self, action):
        return any(action.command.startswith(p) for p in self.rules)

    def end_task(self):
        return None
